def parse_duration(s):
    import re
    pattern = r'^(\d+)([smh])$'
    match = re.match(pattern, s)
    if not match:
        raise ValueError(f"Invalid duration format: {s}")
    value = int(match.group(1))
    unit = match.group(2)
    multipliers = {'s': 1, 'm': 60, 'h': 3600}
    return value * multipliers[unit]

